  1→"use client";
  2→
  3→/**
  4→ * Syntax-highlighted diff renderer for file-modifying tool calls.
  5→ *
  6→ * Uses `@pierre/diffs` (https://diffs.com) — a Shiki-based diff library
  7→ * that renders inside Shadow DOM for style isolation.
  8→ *
  9→ * ## Data flow
 10→ *
 11→ * When Claude calls Edit, Write, or MultiEdit, the tool_use content block
 12→ * contains the file path and before/after strings. These are preserved on
 13→ * {@link ToolCallInfo.input} by `relayChatMessage()` in `use-websocket.ts`.
 14→ * This component converts that input into `oldFile`/`newFile` objects that
 15→ * `MultiFileDiff` can render.
 16→ *
 17→ * ## Tool input shapes
 18→ *
 19→ * - **Edit** — `{ file_path, old_string, new_string }` — search/replace
 20→ *   on a single region. Renders as a diff of the changed fragment only
 21→ *   (not the full file, since we don't have full-file context).
 22→ *
 23→ * - **Write** — `{ file_path, content }` — create or overwrite a file.
 24→ *   Rendered as a "new file" diff with an empty old file.
 25→ *
 26→ * - **MultiEdit** — `{ file_path, edits: [{ old_string, new_string }] }` —
 27→ *   multiple search/replace ops on the same file. The individual hunks are
 28→ *   concatenated with `\n...\n` separators since we lack inter-hunk context.
 29→ *
 30→ * ## Size guard
 31→ *
 32→ * Diffs larger than 100 KB (combined old + new) are silently skipped to
 33→ * avoid freezing the browser on whole-file Write operations.
 34→ *
 35→ * ## Commenting
 36→ *
 37→ * When `onComment` is provided, clicking a line number opens an inline
 38→ * comment input below the diff. On submit, the comment is formatted with
 39→ * file path and line context and sent to the active Claude session via
 40→ * the callback. This uses `@pierre/diffs`' `onLineNumberClick` option
 41→ * in `FileDiffOptions`.
 42→ *
 43→ * ## Usage
 44→ *
 45→ * ```tsx
 46→ * <DiffViewer toolCall={toolCallInfo} onComment={sendMessage} />
 47→ * ```
 48→ *
 49→ * Renders nothing if the tool call has no input or isn't a file-modifying tool.
 50→ *
 51→ * Used by:
 52→ * - {@link CondensedToolGroup} — inline expandable diffs in collapsed view
 53→ * - {@link Message} — automatic diffs below standalone assistant messages
 54→ * - {@link DiffsPanel} — sidebar panel collecting all session diffs
 55→ */
 56→
 57→import { useCallback, useMemo, useRef, useState } from "react";
 58→import { MessageSquare, Send, X } from "lucide-react";
 59→import { MultiFileDiff } from "@pierre/diffs/react";
 60→import type { ToolCallInfo } from "@/lib/types";
 61→import { cn } from "@/lib/utils";
 62→
 63→// ── Tool input type guards ──────────────────────────────────────────────
 64→
 65→/** Shape of the `input` object for the Claude Code `Edit` tool. */
 66→interface EditInput {
 67→  file_path: string;
 68→  old_string: string;
 69→  new_string: string;
 70→}
 71→
 72→/** Shape of the `input` object for the Claude Code `Write` tool. */
 73→interface WriteInput {
 74→  file_path: string;
 75→  content: string;
 76→}
 77→
 78→/** Shape of the `input` object for the Claude Code `MultiEdit` tool. */
 79→interface MultiEditInput {
 80→  file_path: string;
 81→  edits: Array<{ old_string: string; new_string: string }>;
 82→}
 83→
 84→/** Skip rendering for diffs exceeding this combined size (bytes). */
 85→const MAX_CONTENT_SIZE = 100_000;
 86→
 87→/**
 88→ * Build `{ oldFile, newFile }` from a tool call's raw input.
 89→ *
 90→ * Each tool has a different input shape — this function normalizes them
 91→ * into the `{ name, contents }` format that `MultiFileDiff` expects.
 92→ * Returns `null` when the tool call can't be rendered (wrong tool,
 93→ * missing fields, or content too large).
 94→ */
 95→function buildDiffFiles(tc: ToolCallInfo): {
 96→  oldFile: { name: string; contents: string };
 97→  newFile: { name: string; contents: string };
 98→} | null {
 99→  if (!tc.input) return null;
100→
101→  if (tc.name === "Edit") {
102→    const input = tc.input as unknown as EditInput;
103→    if (!input.file_path || input.old_string == null || input.new_string == null) return null;
104→    if (input.old_string.length + input.new_string.length > MAX_CONTENT_SIZE) return null;
105→    return {
106→      oldFile: { name: input.file_path, contents: input.old_string },
107→      newFile: { name: input.file_path, contents: input.new_string },
108→    };
109→  }
110→
111→  if (tc.name === "Write") {
112→    const input = tc.input as unknown as WriteInput;
113→    if (!input.file_path || input.content == null) return null;
114→    if (input.content.length > MAX_CONTENT_SIZE) return null;
115→    return {
116→      oldFile: { name: input.file_path, contents: "" },
117→      newFile: { name: input.file_path, contents: input.content },
118→    };
119→  }
120→
121→  if (tc.name === "MultiEdit") {
122→    const input = tc.input as unknown as MultiEditInput;
123→    if (!input.file_path || !Array.isArray(input.edits)) return null;
124→    const oldParts: string[] = [];
125→    const newParts: string[] = [];
126→    for (const edit of input.edits) {
127→      if (edit.old_string != null) oldParts.push(edit.old_string);
128→      if (edit.new_string != null) newParts.push(edit.new_string);
129→    }
130→    const oldContent = oldParts.join("\n...\n");
131→    const newContent = newParts.join("\n...\n");
132→    if (oldContent.length + newContent.length > MAX_CONTENT_SIZE) return null;
133→    return {
134→      oldFile: { name: input.file_path, contents: oldContent },
135→      newFile: { name: input.file_path, contents: newContent },
136→    };
137→  }
138→
139→  return null;
140→}
141→
142→/** Get the line content from the appropriate file given the side. */
143→function getLineContent(
144→  files: { oldFile: { contents: string }; newFile: { contents: string } },
145→  lineNumber: number,
146→  side: string,
147→): string {
148→  const contents = side === "additions" ? files.newFile.contents : files.oldFile.contents;
149→  const lines = contents.split("\n");
150→  return lines[lineNumber - 1] ?? "";
151→}
152→
153→/**
154→ * Renders a syntax-highlighted diff for a single file-modifying tool call.
155→ *
156→ * @param toolCall — The tool call info with `input` data.
157→ * @param onComment — Optional callback to send a comment message to the
158→ *   active Claude session. When provided, line numbers become clickable.
159→ */
160→export function DiffViewer({
161→  toolCall,
162→  onComment,
163→}: {
164→  toolCall: ToolCallInfo;
165→  onComment?: (message: string) => void;
166→}) {
167→  const files = useMemo(() => buildDiffFiles(toolCall), [toolCall]);
168→  const [commentLine, setCommentLine] = useState<{ lineNumber: number; side: string } | null>(null);
169→  const [commentText, setCommentText] = useState("");
170→  const inputRef = useRef<HTMLInputElement>(null);
171→
172→  const filePath = String(toolCall.input?.file_path ?? "unknown");
173→  const basename = filePath.split("/").pop() ?? filePath;
174→
175→  const handleLineNumberClick = useCallback(
176→    (props: { lineNumber: number; annotationSide: string }) => {
177→      if (!onComment) return;
178→      setCommentLine({ lineNumber: props.lineNumber, side: props.annotationSide });
179→      setCommentText("");
180→      // Focus input on next tick after render
181→      setTimeout(() => inputRef.current?.focus(), 0);
182→    },
183→    [onComment],
184→  );
185→
186→  function handleSubmitComment() {
187→    if (!commentText.trim() || !commentLine || !onComment || !files) return;
188→    const lineContent = getLineContent(files, commentLine.lineNumber, commentLine.side);
189→    const sideLabel = commentLine.side === "additions" ? "new" : "old";
190→    const message = lineContent.trim()
191→      ? `Regarding \`${filePath}\` line ${commentLine.lineNumber} (${sideLabel}):\n\`\`\`\n${lineContent}\n\`\`\`\n${commentText.trim()}`
192→      : `Regarding \`${filePath}\` line ${commentLine.lineNumber} (${sideLabel}): ${commentText.trim()}`;
193→    onComment(message);
194→    setCommentLine(null);
195→    setCommentText("");
196→  }
197→
198→  function handleKeyDown(e: React.KeyboardEvent) {
199→    if (e.key === "Enter" && !e.shiftKey) {
200→      e.preventDefault();
201→      handleSubmitComment();
202→    } else if (e.key === "Escape") {
203→      setCommentLine(null);
204→      setCommentText("");
205→    }
206→  }
207→
208→  if (!files) return null;
209→
210→  const options = onComment
211→    ? {
212→        themeType: "dark" as const,
213→        onLineNumberClick: handleLineNumberClick,
214→      }
215→    : { themeType: "dark" as const };
216→
217→  return (
218→    <div className="mt-1 overflow-hidden rounded-md border border-border">
219→      <MultiFileDiff
220→        oldFile={files.oldFile}
221→        newFile={files.newFile}
222→        options={options}
223→      />
224→      {commentLine && (
225→        <div className="flex items-center gap-2 border-t border-border bg-muted/50 px-2 py-1.5">
226→          <MessageSquare className="size-3 shrink-0 text-muted-foreground" />
227→          <span className="shrink-0 text-[10px] text-muted-foreground font-mono">
228→            {basename}:{commentLine.lineNumber}
229→          </span>
230→          <input
231→            ref={inputRef}
232→            type="text"
233→            value={commentText}
234→            onChange={(e) => setCommentText(e.target.value)}
235→            onKeyDown={handleKeyDown}
236→            placeholder="Comment on this line..."
237→            className="flex-1 bg-transparent text-xs outline-none placeholder:text-muted-foreground/50"
238→          />
239→          <button
240→            onClick={handleSubmitComment}
241→            disabled={!commentText.trim()}
242→            className={cn(
243→              "rounded p-1 transition-colors",
244→              commentText.trim()
245→                ? "text-primary hover:bg-primary/10"
246→                : "text-muted-foreground/30"
247→            )}
248→            title="Send comment"
249→          >
250→            <Send className="size-3" />
251→          </button>
252→          <button
253→            onClick={() => { setCommentLine(null); setCommentText(""); }}
254→            className="rounded p-1 text-muted-foreground hover:bg-muted/50 transition-colors"
255→            title="Cancel"
256→          >
257→            <X className="size-3" />
258→          </button>
259→        </div>
260→      )}
261→    </div>
262→  );
263→}
264→

  1→"use client";
  2→
  3→/**
  4→ * Right-side drawer panel that collects all file diffs from the active
  5→ * agent session into a single scrollable view, grouped by file path.
  6→ *
  7→ * ## Architecture
  8→ *
  9→ * Follows the same pattern as {@link TaskPanel} in `kanban-board.tsx`:
 10→ * - Toggled via a button in the {@link StatusBar} (GitCompareArrows icon)
 11→ * - State lives in `app/dashboard/page.tsx` (`showDiffs` boolean)
 12→ * - Rendered as a fixed right-side drawer (w-96) with mobile backdrop
 13→ * - Props threaded: page → Chat → StatusBar for the toggle button
 14→ *
 15→ * ## Data flow
 16→ *
 17→ * The panel receives `activeMessages` (the current agent's processed
 18→ * chat messages) from the page component. It derives the diff list
 19→ * via `useMemo` — no WebSocket hook changes or server-side support
 20→ * is needed. The diff data is already on each `ChatMessage.toolCalls`
 21→ * entry as `ToolCallInfo.input`.
 22→ *
 23→ * ```
 24→ * activeMessages → groupByFile() → FileGroup[] → FileGroupItem → DiffViewer
 25→ * ```
 26→ *
 27→ * ## Grouping
 28→ *
 29→ * Diffs are grouped by absolute file path using insertion order (Map).
 30→ * Multiple edits to the same file appear under one collapsible section,
 31→ * each rendered as a separate {@link DiffViewer}. This lets you see the
 32→ * full edit history for a file in chronological order.
 33→ */
 34→
 35→import { useMemo, useState } from "react";
 36→import { ChevronRight, X } from "lucide-react";
 37→import { Button } from "@/components/ui/button";
 38→import { DiffViewer } from "./diff-viewer";
 39→import { Tip } from "@/components/ui/tip";
 40→import { cn } from "@/lib/utils";
 41→import type { ChatMessage, ToolCallInfo } from "@/lib/types";
 42→
 43→/** Tool names whose inputs contain diff data (file_path + old/new strings). */
 44→const DIFF_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);
 45→
 46→/** A group of diffs for a single file path. */
 47→interface FileGroup {
 48→  filePath: string;
 49→  diffs: ToolCallInfo[];
 50→}
 51→
 52→/**
 53→ * Walk all messages and collect file-modifying tool calls, grouped by
 54→ * file path. Preserves insertion order so files appear in the order
 55→ * they were first touched.
 56→ */
 57→function groupByFile(messages: ChatMessage[]): FileGroup[] {
 58→  const map = new Map<string, ToolCallInfo[]>();
 59→  for (const msg of messages) {
 60→    for (const tc of msg.toolCalls ?? []) {
 61→      if (!tc.input || !DIFF_TOOLS.has(tc.name)) continue;
 62→      const filePath = String(tc.input.file_path ?? "");
 63→      if (!filePath) continue;
 64→      let group = map.get(filePath);
 65→      if (!group) {
 66→        group = [];
 67→        map.set(filePath, group);
 68→      }
 69→      group.push(tc);
 70→    }
 71→  }
 72→  return Array.from(map, ([filePath, diffs]) => ({ filePath, diffs }));
 73→}
 74→
 75→/** Collapsible section for a single file's diffs. Expanded by default. */
 76→function FileGroupItem({ group, onComment }: { group: FileGroup; onComment?: (message: string) => void }) {
 77→  const [expanded, setExpanded] = useState(true);
 78→  const basename = group.filePath.split("/").pop() ?? group.filePath;
 79→
 80→  return (
 81→    <div className="border-b border-border last:border-b-0">
 82→      <button
 83→        onClick={() => setExpanded((v) => !v)}
 84→        className="flex w-full items-center gap-2 px-3 py-2 text-xs hover:bg-muted/50 transition-colors"
 85→      >
 86→        <ChevronRight
 87→          className={cn(
 88→            "size-3 shrink-0 transition-transform",
 89→            expanded && "rotate-90"
 90→          )}
 91→        />
 92→        <Tip text={group.filePath}><span className="font-mono font-medium truncate">{basename}</span></Tip>
 93→        <span className="text-muted-foreground/60 ml-auto shrink-0">
 94→          {group.diffs.length} {group.diffs.length === 1 ? "edit" : "edits"}
 95→        </span>
 96→      </button>
 97→      {expanded && (
 98→        <div className="px-2 pb-2 space-y-2">
 99→          {group.diffs.map((tc, i) => (
100→            <DiffViewer key={tc.toolUseId ?? i} toolCall={tc} onComment={onComment} />
101→          ))}
102→        </div>
103→      )}
104→    </div>
105→  );
106→}
107→
108→/**
109→ * Sidebar panel listing all file diffs from the current agent session.
110→ *
111→ * @param messages — The active agent's `ChatMessage[]` from `useWebSocket`.
112→ *   File-modifying tool calls are extracted and grouped by file path.
113→ * @param onSendMessage — Callback to send a comment to the active session.
114→ * @param onClose — Callback to hide the panel (sets `showDiffs` to false).
115→ */
116→export function DiffsPanel({
117→  messages,
118→  onSendMessage,
119→  onClose,
120→}: {
121→  messages: ChatMessage[];
122→  onSendMessage?: (content: string) => void;
123→  onClose: () => void;
124→}) {
125→  const fileGroups = useMemo(() => groupByFile(messages), [messages]);
126→  const totalDiffs = fileGroups.reduce((sum, g) => sum + g.diffs.length, 0);
127→
128→  return (
129→    <div className="flex h-full min-w-0 flex-col overflow-hidden">
130→      {/* Header */}
131→      <div className="flex items-center justify-between border-b px-3 py-2">
132→        <div className="flex items-center gap-2">
133→          <span className="text-xs font-semibold">Diffs</span>
134→          {totalDiffs > 0 && (
135→            <span className="rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-mono text-muted-foreground">
136→              {totalDiffs}
137→            </span>
138→          )}
139→        </div>
140→        <Button variant="ghost" size="icon-xs" onClick={onClose} title="Close">
141→          <X className="size-3.5" />
142→        </Button>
143→      </div>
144→
145→      {/* Content */}
146→      <div className="flex-1 overflow-y-auto">
147→        {fileGroups.length === 0 ? (
148→          <div className="flex h-full items-center justify-center text-xs text-muted-foreground">
149→            No file changes yet
150→          </div>
151→        ) : (
152→          fileGroups.map((group) => (
153→            <FileGroupItem key={group.filePath} group={group} onComment={onSendMessage} />
154→          ))
155→        )}
156→      </div>
157→    </div>
158→  );
159→}
160→

  1→/**
  2→ * Shared type definitions for the thos dashboard.
  3→ *
  4→ * Three categories:
  5→ * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
  6→ *    `--sdk-url` WebSocket connection (CLI → WS server).
  7→ * 2. **Browser ↔ Server** — messages exchanged between the React client
  8→ *    and the standalone WS relay server.
  9→ * 3. **UI state** — view-model types consumed by React components.
 10→ *
 11→ * ## Key architecture notes
 12→ *
 13→ * - On browser connect, the server sends `agent_list` + `task_list` only.
 14→ * - Message histories are loaded lazily: the browser sends
 15→ *   `request_history` when selecting an agent, and the server responds
 16→ *   with `message_history` for that single agent.
 17→ * - Live messages for active agents are broadcast via `relay` in real time.
 18→ * - See `server/ws.ts` and `hooks/use-websocket.ts` for implementation.
 19→ */
 20→
 21→// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────
 22→
 23→/**
 24→ * Sent once after the first user prompt is received. Contains session
 25→ * metadata like the model name, working directory, and available tools.
 26→ */
 27→export interface ClaudeSystemInit {
 28→  type: "system";
 29→  subtype: "init";
 30→  session_id: string;
 31→  tools: unknown[];
 32→  mcp_servers: unknown[];
 33→  model: string;
 34→  cwd: string;
 35→}
 36→
 37→/**
 38→ * An assistant turn. `message.content` is an array of content blocks
 39→ * (text, tool_use, tool_result) that may arrive incrementally — each
 40→ * NDJSON line is a complete snapshot of the message so far.
 41→ */
 42→export interface ClaudeAssistant {
 43→  type: "assistant";
 44→  message: {
 45→    id: string;
 46→    role: "assistant";
 47→    content: AssistantContentBlock[];
 48→    model: string;
 49→    stop_reason: string | null;
 50→  };
 51→  session_id: string;
 52→}
 53→
 54→/** A single content block inside an assistant message. */
 55→export type AssistantContentBlock =
 56→  | { type: "text"; text: string }
 57→  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 58→  | { type: "tool_result"; tool_use_id: string; content: string };
 59→
 60→/**
 61→ * Terminal message for a session. Includes cost/duration metrics.
 62→ * `is_error` is true when `subtype` is `"error"`.
 63→ */
 64→export interface ClaudeResult {
 65→  type: "result";
 66→  subtype: "success" | "error";
 67→  result?: string;
 68→  error?: string;
 69→  session_id: string;
 70→  cost_usd: number;
 71→  total_cost_usd?: number;
 72→  duration_ms: number;
 73→  duration_api_ms: number;
 74→  is_error: boolean;
 75→  num_turns: number;
 76→}
 77→
 78→/**
 79→ * Claude is requesting permission to execute a tool. The dashboard must
 80→ * reply with a `control_response` (allow / deny) before the CLI proceeds.
 81→ *
 82→ * Wire format uses a nested `request` object with `request_id` at the
 83→ * top level for correlation (matches Companion protocol docs).
 84→ */
 85→export interface ClaudeControlRequest {
 86→  type: "control_request";
 87→  request_id: string;
 88→  request: {
 89→    subtype: "can_use_tool";
 90→    tool_name: string;
 91→    input: Record<string, unknown>;
 92→    tool_use_id?: string;
 93→    description?: string;
 94→  };
 95→  session_id?: string;
 96→}
 97→
 98→/**
 99→ * Hook lifecycle events emitted during CLI startup. `hook_response` is
100→ * the signal that the CLI is ready to receive the first user prompt.
101→ */
102→export interface ClaudeSystemHook {
103→  type: "system";
104→  subtype: "hook_started" | "hook_response";
105→  session_id?: string;
106→}
107→
108→/** Discriminated union of all known Claude NDJSON message shapes. */
109→export type ClaudeMessage =
110→  | ClaudeSystemInit
111→  | ClaudeAssistant
112→  | ClaudeResult
113→  | ClaudeControlRequest
114→  | ClaudeSystemHook
115→  | { type: string; subtype?: string; [key: string]: unknown };
116→
117→// ── Workspaces ───────────────────────────────────────────────────────────
118→
119→/** A workspace represents a project directory. */
120→export interface Workspace {
121→  id: string;
122→  name: string;
123→  cwd: string;
124→  createdAt: number;
125→}
126→
127→/** A directory entry returned by the server-side folder browser. */
128→export interface DirectoryEntry {
129→  name: string;
130→  path: string;
131→}
132→
133→// ── Browser ↔ Server messages ─────────────────────────────────────────────
134→
135→/** Browser asks the server to spawn a new Claude CLI process. */
136→export interface BrowserSpawn {
137→  type: "spawn";
138→  prompt: string;
139→  workspaceId?: string;
140→  /** Optional model override (e.g. "claude-opus-4-20250514", "qwen3-coder"). */
141→  model?: string;
142→}
143→
144→/** Browser sends a follow-up message to an already-running Claude session. */
145→export interface BrowserSendMessage {
146→  type: "send_message";
147→  agentId: string;
148→  content: string;
149→}
150→
151→/** Browser responds to a tool approval request (allow or deny). */
152→export interface BrowserControlResponse {
153→  type: "control_response";
154→  agentId: string;
155→  request_id: string;
156→  allow: boolean;
157→}
158→
159→/** Browser asks the server to kill a running agent's tmux session + CLI. */
160→export interface BrowserKillAgent {
161→  type: "kill_agent";
162→  agentId: string;
163→}
164→
165→/** Browser asks the server to permanently delete an agent. */
166→export interface BrowserDeleteAgent {
167→  type: "delete_agent";
168→  agentId: string;
169→}
170→
171→/** Browser asks the server to rename an agent. */
172→export interface BrowserRenameAgent {
173→  type: "rename_agent";
174→  agentId: string;
175→  label: string;
176→}
177→
178→/** Browser asks the server to clear an agent's message history. */
179→export interface BrowserClearHistory {
180→  type: "clear_history";
181→  agentId: string;
182→}
183→
184→/** Browser asks the server to pin or unpin an agent. */
185→export interface BrowserPinAgent {
186→  type: "pin_agent";
187→  agentId: string;
188→  pinned: boolean;
189→}
190→
191→/** Browser asks the server to icebox or un-icebox an agent. */
192→export interface BrowserIceboxAgent {
193→  type: "icebox_agent";
194→  agentId: string;
195→  iceboxed: boolean;
196→}
197→
198→/** Browser asks the server to move an agent to a different workspace. */
199→export interface BrowserMoveAgent {
200→  type: "move_agent";
201→  agentId: string;
202→  workspaceId: string | null;
203→}
204→
205→/** Browser requests message history for a specific agent (lazy loading). */
206→export interface BrowserRequestHistory {
207→  type: "request_history";
208→  agentId: string;
209→}
210→
211→/** Browser asks the server to create a new task. */
