 97→    );
 98→  }
 99→
100→  const isUser = message.role === "user";
101→
102→  return (
103→    <div className={cn("flex flex-col gap-0.5", isUser ? "items-end" : "items-start")}>
104→      <div
105→        className={cn(
106→          "group relative max-w-[90%] md:max-w-[80%] rounded-lg px-3 py-2 text-sm",
107→          isUser
108→            ? "bg-primary text-primary-foreground whitespace-pre-wrap"
109→            : "bg-secondary text-secondary-foreground prose-msg"
110→        )}
111→      >
112→        {isUser ? (
113→          message.content
114→        ) : (
115→          <Markdown remarkPlugins={[remarkGfm]}>{message.content}</Markdown>
116→        )}
117→        {!isUser && message.toolCalls && (
118→          <div className="mt-2 space-y-2">
