  3→/**
  4→ * Collapsible group for consecutive tool-only assistant messages.
  5→ *
  6→ * When Claude runs multiple tools in a row without any prose text,
  7→ * {@link condenseMessages} in `lib/condense-messages.ts` groups them
  8→ * into a {@link CondensedGroup}. This component renders that group.
  9→ *
 10→ * ## Two-level expand
 11→ *
 12→ * 1. **Group level** — The top chevron toggles between the compact
 13→ *    per-tool-call summary (collapsed) and the full message bubbles
 14→ *    (expanded). This is the original behavior.
 15→ *
 16→ * 2. **Diff level** — In the collapsed view, file-modifying tool calls
 17→ *    (Edit, Write, MultiEdit) show the file basename and are clickable.
 18→ *    Clicking one toggles an inline {@link DiffViewer} for just that
 19→ *    tool call, without expanding the whole group. Multiple diffs can
 20→ *    be open at once (tracked in the `expandedDiffs` Set).
 21→ *
 22→ * Non-diff tool calls (Read, Bash, Grep, etc.) continue to show the
 23→ * truncated `resultPreview` text as before.
 24→ */
 25→
 26→import { memo, useState } from "react";
 27→import { ChevronRight } from "lucide-react";
 28→import type { CondensedGroup } from "@/lib/condense-messages";
 29→import type { ToolCallInfo } from "@/lib/types";
 30→import { Message } from "./message";
 31→import { DiffViewer } from "./diff-viewer";
 32→import { Tip } from "@/components/ui/tip";
 33→import { cn } from "@/lib/utils";
 34→
 35→/** Colored dot per common tool name (used in the compact summary line). */
 36→const TOOL_COLORS: Record<string, string> = {
 37→  Read: "bg-blue-400",
 38→  Write: "bg-green-400",
 39→  Edit: "bg-yellow-400",
 40→  Bash: "bg-orange-400",
 41→  Glob: "bg-purple-400",
 42→  Grep: "bg-cyan-400",
 43→  WebFetch: "bg-pink-400",
 44→  Task: "bg-indigo-400",
 45→  TodoWrite: "bg-teal-400",
 46→};
 47→
 48→/** Tool names that produce renderable diffs (same set as in diff-viewer). */
 49→const DIFF_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);
 50→
 51→export const CondensedToolGroup = memo(function CondensedToolGroup({ group, onSendMessage }: { group: CondensedGroup; onSendMessage?: (content: string) => void }) {
 52→  /** Whether the full message list is shown (group-level expand). */
 53→  const [expanded, setExpanded] = useState(false);
 54→  /** Which individual diffs are open in the collapsed view (by key). */
 55→  const [expandedDiffs, setExpandedDiffs] = useState<Set<string>>(new Set());
 56→
 57→  // Collect all tool calls with previews for the collapsed view
 58→  const allToolCalls: ToolCallInfo[] = [];
 59→  for (const msg of group.messages) {
 60→    for (const tc of msg.toolCalls ?? []) {
 61→      allToolCalls.push(tc);
 62→    }
 63→  }
 64→
 65→  function toggleDiff(key: string) {
 66→    setExpandedDiffs((prev) => {
 67→      const next = new Set(prev);
 68→      if (next.has(key)) next.delete(key);
 69→      else next.add(key);
 70→      return next;
 71→    });
 72→  }
 73→
 74→  return (
 75→    <div className="py-1">
 76→      <button
 77→        onClick={() => setExpanded((v) => !v)}
 78→        aria-expanded={expanded}
 79→        className="flex w-full items-center gap-2 rounded-md px-3 py-1.5 text-xs text-muted-foreground hover:bg-muted/50 transition-colors"
 80→      >
 81→        <ChevronRight
 82→          className={cn(
 83→            "size-3 shrink-0 transition-transform",
 84→            expanded && "rotate-90"
 85→          )}
 86→        />
 87→        <span className="font-mono">{group.summary}</span>
 88→      </button>
 89→
 90→      {!expanded && allToolCalls.length > 0 && (
 91→        <div className="ml-5 mt-0.5 space-y-0.5 pl-3">
 92→          {allToolCalls.map((tc, i) => {
 93→            const key = `${tc.toolUseId ?? "tc"}-${i}`;
 94→            const hasDiff = tc.input && DIFF_TOOLS.has(tc.name);
 95→            const diffOpen = expandedDiffs.has(key);
 96→
 97→            return (
 98→              <div key={key}>
 99→                <div
100→                  className={cn(
101→                    "flex items-center gap-1.5 text-[10px] text-muted-foreground/70 truncate",
102→                    hasDiff && "cursor-pointer hover:text-muted-foreground"
103→                  )}
104→                  onClick={hasDiff ? () => toggleDiff(key) : undefined}
105→                >
106→                  <span className={cn("inline-block size-1.5 shrink-0 rounded-full", TOOL_COLORS[tc.name] ?? "bg-muted-foreground/50")} />
107→                  <span className="font-mono shrink-0">{tc.name}</span>
108→                  {hasDiff && tc.input?.file_path ? (
109→                    <Tip text={String(tc.input.file_path)}>
110→                      <span className="truncate font-mono opacity-80">
111→                        {String(tc.input.file_path).split("/").pop()}
112→                      </span>
113→                    </Tip>
114→                  ) : tc.resultPreview ? (
115→                    <Tip text={tc.resultPreview}><span className="truncate opacity-60">{tc.resultPreview}</span></Tip>
116→                  ) : null}
117→                </div>
118→                {hasDiff && diffOpen && (
119→                  <div className="mt-1 mb-1">
120→                    <DiffViewer toolCall={tc} onComment={onSendMessage} />
121→                  </div>
122→                )}
123→              </div>
124→            );
125→          })}
126→        </div>
127→      )}
128→
129→      {expanded && (
130→        <div className="ml-5 mt-1 space-y-1 border-l border-muted pl-3">
131→          {group.messages.map((msg) => (
132→            <Message key={msg.id} message={msg} onSendMessage={onSendMessage} />
133→          ))}
134→        </div>
135→      )}
136→    </div>
137→  );
138→});
