 93→/**
 94→ * Extract displayable text from a Claude assistant message.
 95→ * Content blocks may be text, tool_use, or tool_result — each is
 96→ * handled defensively since the array structure can vary.
 97→ */
 98→function extractText(msg: ClaudeAssistant): string {
 99→  const blocks = msg.message?.content;
100→  if (!blocks || !Array.isArray(blocks)) return "";
101→  return blocks
102→    .map((b) => {
103→      if (b.type === "text") return b.text;
104→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
105→      if (b.type === "tool_result") {
106→        const c = (b as { content?: unknown }).content;
107→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
108→      }
109→      return "";
110→    })
111→    .filter(Boolean)
112→    .join("\n");
113→}
114→
115→/** Module-level counter for generating unique message IDs. */
116→let msgCounter = 0;
117→function nextId() {
118→  return `msg-${Date.now()}-${++msgCounter}`;
119→}
120→
121→/**
122→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
123→ * Used both for live messages and for replaying message_history.
124→ */
125→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
126→  if (relayMsg.type === "relay") {
127→    const msg = relayMsg.message;
128→
129→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
130→      const init = msg as ClaudeSystemInit;
131→      return {
132→        id: nextId(),
133→        role: "system",
134→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
135→        timestamp: Date.now(),
136→      };
137→    }
138→
139→    if (msg.type === "user") {
140→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
141→      // Only render human-typed user messages (string content).
142→      // CLI tool_result messages have array content — these are internal
143→      // protocol messages and are only visible in the raw message viewer.
144→      if (typeof rawContent !== "string") return null;
145→      if (!rawContent.trim()) return null;
146→      return {
147→        id: nextId(),
148→        role: "user",
149→        content: rawContent,
150→        timestamp: Date.now(),
151→      };
152→    }
153→
154→    if (msg.type === "assistant") {
155→      const assistant = msg as ClaudeAssistant;
156→      const text = extractText(assistant);
157→      if (!text) return null;
158→
159→      const blocks = assistant.message?.content ?? [];
160→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
161→
162→      // Build a map of tool_result blocks keyed by tool_use_id for preview extraction
163→      const resultMap = new Map<string, string>();
164→      for (const b of blocks) {
165→        if (b.type === "tool_result") {
166→          const tr = b as { tool_use_id?: string; content?: unknown };
167→          if (tr.tool_use_id) {
168→            const raw = typeof tr.content === "string" ? tr.content : JSON.stringify(tr.content ?? "");
169→            const firstLine = raw.split("\n")[0];
170→            resultMap.set(tr.tool_use_id, firstLine.length > 120 ? firstLine.slice(0, 117) + "..." : firstLine);
171→          }
172→        }
173→      }
174→
175→      // Build ToolCallInfo for each tool_use block. For file-modifying tools
176→      // (Edit, Write, MultiEdit), the raw `input` object is preserved so that
177→      // DiffViewer can render syntax-highlighted before/after diffs. Other
178→      // tools only keep the name and result preview to avoid carrying
179→      // unnecessary data (e.g. Read file contents, Bash output).
180→      const DIFF_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);
181→      const toolCalls: ToolCallInfo[] = blocks
182→        .filter((b) => b.type === "tool_use")
183→        .map((b) => {
184→          const tu = b as { name: string; id: string; input: Record<string, unknown> };
185→          const info: ToolCallInfo = {
186→            name: tu.name,
187→            toolUseId: tu.id,
188→            resultPreview: resultMap.get(tu.id),
189→          };
190→          if (DIFF_TOOLS.has(tu.name)) {
191→            info.input = tu.input;
192→          }
193→          return info;
194→        });
195→      const isToolOnly = !hasText && toolCalls.length > 0;
196→
197→      return {
198→        id: nextId(),
199→        role: "assistant",
200→        content: text,
201→        timestamp: Date.now(),
202→        toolCalls,
203→        isToolOnly,
204→      };
205→    }
206→
207→    if (msg.type === "result") {
208→      const result = msg as ClaudeResult;
209→      const summary = result.is_error
210→        ? `Error: ${result.error}`
211→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
212→      return {
213→        id: nextId(),
214→        role: "system",
215→        content: summary,
216→        timestamp: Date.now(),
217→      };
218→    }
219→
220→    if (msg.type === "control_request") {
221→      const cr = msg as ClaudeControlRequest;
222→
223→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
224→      if (cr.request.tool_name === "AskUserQuestion") {
225→        const input = cr.request.input as { questions?: UserQuestion[] };
226→        const questions = Array.isArray(input.questions) ? input.questions : [];
227→        return {
228→          id: nextId(),
229→          role: "system",
230→          content: "Question from Claude",
231→          timestamp: Date.now(),
232→          userQuestion: {
233→            requestId: cr.request_id,
234→            questions,
235→          },
236→        };
237→      }
238→
239→      return {
240→        id: nextId(),
241→        role: "system",
242→        content: `Tool approval requested: ${cr.request.tool_name}`,
243→        timestamp: Date.now(),
244→        controlRequest: {
245→          id: cr.request_id,
246→          tool_name: cr.request.tool_name,
247→          input: cr.request.input,
248→          description: cr.request.description,
249→        },
250→      };
251→    }
252→  }
253→
254→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
255→    return {
256→      id: nextId(),
257→      role: "system",
258→      content: `Error: ${relayMsg.error}`,
259→      timestamp: Date.now(),
260→    };
261→  }
262→
263→  return null;
264→}
