 1→import type { ChatMessage } from "@/lib/types";
 2→
 3→export interface SingleItem {
 4→  kind: "single";
 5→  message: ChatMessage;
 6→}
 7→
 8→export interface CondensedGroup {
 9→  kind: "condensed";
10→  id: string;
11→  messages: ChatMessage[];
12→  summary: string;
13→  toolCounts: Record<string, number>;
14→  count: number;
15→  timestamp: number;
16→}
17→
18→export type DisplayItem = SingleItem | CondensedGroup;
19→
20→/**
21→ * Groups consecutive tool-only assistant messages into collapsible summaries.
22→ * Messages with text content, control requests, user questions, and non-assistant
23→ * messages all break the grouping sequence.
24→ *
25→ * Only condenses when 2+ consecutive tool-only messages are found.
26→ */
27→export function condenseMessages(messages: ChatMessage[]): DisplayItem[] {
28→  const result: DisplayItem[] = [];
29→  let i = 0;
30→
31→  while (i < messages.length) {
32→    const msg = messages[i];
33→
34→    if (msg.isToolOnly) {
35→      const group: ChatMessage[] = [];
36→      while (i < messages.length && messages[i].isToolOnly) {
37→        group.push(messages[i]);
38→        i++;
39→      }
40→
41→      if (group.length >= 2) {
42→        const toolCounts: Record<string, number> = {};
43→        for (const m of group) {
44→          for (const tc of m.toolCalls ?? []) {
45→            toolCounts[tc.name] = (toolCounts[tc.name] ?? 0) + 1;
46→          }
47→        }
48→
49→        const breakdown = Object.entries(toolCounts)
50→          .map(([name, count]) => `${name} x${count}`)
51→          .join(", ");
52→        const total = Object.values(toolCounts).reduce((a, b) => a + b, 0);
53→
54→        result.push({
55→          kind: "condensed",
56→          id: `group-${group[0].id}`,
57→          messages: group,
58→          summary: `${total} tool calls (${breakdown})`,
59→          toolCounts,
60→          count: group.length,
61→          timestamp: group[0].timestamp,
62→        });
63→      } else {
64→        result.push({ kind: "single", message: group[0] });
65→      }
66→    } else {
67→      result.push({ kind: "single", message: msg });
68→      i++;
69→    }
70→  }
71→
72→  return result;
73→}
