  2→
  3→/**
  4→ * Syntax-highlighted diff renderer for file-modifying tool calls.
  5→ *
  6→ * Uses `@pierre/diffs` (https://diffs.com) — a Shiki-based diff library
  7→ * that renders inside Shadow DOM for style isolation.
  8→ *
  9→ * ## Data flow
 10→ *
 11→ * When Claude calls Edit, Write, or MultiEdit, the tool_use content block
 12→ * contains the file path and before/after strings. These are preserved on
 13→ * {@link ToolCallInfo.input} by `relayChatMessage()` in `use-websocket.ts`.
 14→ * This component converts that input into `oldFile`/`newFile` objects that
 15→ * `MultiFileDiff` can render.
 16→ *
 17→ * ## Tool input shapes
 18→ *
 19→ * - **Edit** — `{ file_path, old_string, new_string }` — search/replace
 20→ *   on a single region. Renders as a diff of the changed fragment only
 21→ *   (not the full file, since we don't have full-file context).
 22→ *
 23→ * - **Write** — `{ file_path, content }` — create or overwrite a file.
 24→ *   Rendered as a "new file" diff with an empty old file.
 25→ *
 26→ * - **MultiEdit** — `{ file_path, edits: [{ old_string, new_string }] }` —
 27→ *   multiple search/replace ops on the same file. The individual hunks are
 28→ *   concatenated with `\n...\n` separators since we lack inter-hunk context.
 29→ *
 30→ * ## Size guard
 31→ *
 32→ * Diffs larger than 100 KB (combined old + new) are silently skipped to
 33→ * avoid freezing the browser on whole-file Write operations.
 34→ *
 35→ * ## Commenting
 36→ *
 37→ * When `onComment` is provided, clicking a line number opens an inline
 38→ * comment input below the diff. On submit, the comment is formatted with
 39→ * file path and line context and sent to the active Claude session via
 40→ * the callback. This uses `@pierre/diffs`' `onLineNumberClick` option
 41→ * in `FileDiffOptions`.
 42→ *
 43→ * ## Usage
 44→ *
 45→ * ```tsx
 46→ * <DiffViewer toolCall={toolCallInfo} onComment={sendMessage} />
 47→ * ```
 48→ *
 49→ * Renders nothing if the tool call has no input or isn't a file-modifying tool.
 50→ *
 51→ * Used by:
 52→ * - {@link CondensedToolGroup} — inline expandable diffs in collapsed view
 53→ * - {@link Message} — automatic diffs below standalone assistant messages
 54→ * - {@link DiffsPanel} — sidebar panel collecting all session diffs
 55→ */
 56→
 57→import { useCallback, useMemo, useRef, useState } from "react";
 58→import { MessageSquare, Send, X } from "lucide-react";
 59→import { MultiFileDiff } from "@pierre/diffs/react";
 60→import type { ToolCallInfo } from "@/lib/types";
 61→import { cn } from "@/lib/utils";
 62→
 63→// ── Tool input type guards ──────────────────────────────────────────────
 64→
 65→/** Shape of the `input` object for the Claude Code `Edit` tool. */
 66→interface EditInput {
 67→  file_path: string;
 68→  old_string: string;
 69→  new_string: string;
 70→}
 71→
 72→/** Shape of the `input` object for the Claude Code `Write` tool. */
 73→interface WriteInput {
 74→  file_path: string;
 75→  content: string;
 76→}
 77→
 78→/** Shape of the `input` object for the Claude Code `MultiEdit` tool. */
 79→interface MultiEditInput {
 80→  file_path: string;
 81→  edits: Array<{ old_string: string; new_string: string }>;
 82→}
 83→
 84→/** Skip rendering for diffs exceeding this combined size (bytes). */
 85→const MAX_CONTENT_SIZE = 100_000;
 86→
 87→/**
 88→ * Build `{ oldFile, newFile }` from a tool call's raw input.
 89→ *
 90→ * Each tool has a different input shape — this function normalizes them
 91→ * into the `{ name, contents }` format that `MultiFileDiff` expects.
 92→ * Returns `null` when the tool call can't be rendered (wrong tool,
 93→ * missing fields, or content too large).
 94→ */
 95→function buildDiffFiles(tc: ToolCallInfo): {
 96→  oldFile: { name: string; contents: string };
 97→  newFile: { name: string; contents: string };
 98→} | null {
 99→  if (!tc.input) return null;
100→
101→  if (tc.name === "Edit") {
102→    const input = tc.input as unknown as EditInput;
103→    if (!input.file_path || input.old_string == null || input.new_string == null) return null;
104→    if (input.old_string.length + input.new_string.length > MAX_CONTENT_SIZE) return null;
105→    return {
106→      oldFile: { name: input.file_path, contents: input.old_string },
107→      newFile: { name: input.file_path, contents: input.new_string },
108→    };
109→  }
110→
111→  if (tc.name === "Write") {
112→    const input = tc.input as unknown as WriteInput;
113→    if (!input.file_path || input.content == null) return null;
114→    if (input.content.length > MAX_CONTENT_SIZE) return null;
115→    return {
116→      oldFile: { name: input.file_path, contents: "" },
117→      newFile: { name: input.file_path, contents: input.content },
118→    };
119→  }
120→
121→  if (tc.name === "MultiEdit") {
122→    const input = tc.input as unknown as MultiEditInput;
123→    if (!input.file_path || !Array.isArray(input.edits)) return null;
124→    const oldParts: string[] = [];
125→    const newParts: string[] = [];
126→    for (const edit of input.edits) {
127→      if (edit.old_string != null) oldParts.push(edit.old_string);
128→      if (edit.new_string != null) newParts.push(edit.new_string);
129→    }
130→    const oldContent = oldParts.join("\n...\n");
131→    const newContent = newParts.join("\n...\n");
132→    if (oldContent.length + newContent.length > MAX_CONTENT_SIZE) return null;
133→    return {
134→      oldFile: { name: input.file_path, contents: oldContent },
135→      newFile: { name: input.file_path, contents: newContent },
136→    };
137→  }
138→
139→  return null;
140→}
141→
142→/** Get the line content from the appropriate file given the side. */
143→function getLineContent(
144→  files: { oldFile: { contents: string }; newFile: { contents: string } },
145→  lineNumber: number,
146→  side: string,
147→): string {
148→  const contents = side === "additions" ? files.newFile.contents : files.oldFile.contents;
149→  const lines = contents.split("\n");
150→  return lines[lineNumber - 1] ?? "";
151→}
152→
153→/**
154→ * Renders a syntax-highlighted diff for a single file-modifying tool call.
155→ *
156→ * @param toolCall — The tool call info with `input` data.
157→ * @param onComment — Optional callback to send a comment message to the
158→ *   active Claude session. When provided, line numbers become clickable.
159→ */
160→export function DiffViewer({
161→  toolCall,
162→  onComment,
163→}: {
164→  toolCall: ToolCallInfo;
165→  onComment?: (message: string) => void;
166→}) {
167→  const files = useMemo(() => buildDiffFiles(toolCall), [toolCall]);
168→  const [commentLine, setCommentLine] = useState<{ lineNumber: number; side: string } | null>(null);
169→  const [commentText, setCommentText] = useState("");
170→  const inputRef = useRef<HTMLInputElement>(null);
171→
172→  const filePath = String(toolCall.input?.file_path ?? "unknown");
173→  const basename = filePath.split("/").pop() ?? filePath;
174→
175→  const handleLineNumberClick = useCallback(
176→    (props: { lineNumber: number; annotationSide: string }) => {
177→      if (!onComment) return;
178→      setCommentLine({ lineNumber: props.lineNumber, side: props.annotationSide });
179→      setCommentText("");
180→      // Focus input on next tick after render
181→      setTimeout(() => inputRef.current?.focus(), 0);
182→    },
183→    [onComment],
184→  );
185→
186→  function handleSubmitComment() {
187→    if (!commentText.trim() || !commentLine || !onComment || !files) return;
188→    const lineContent = getLineContent(files, commentLine.lineNumber, commentLine.side);
189→    const sideLabel = commentLine.side === "additions" ? "new" : "old";
190→    const message = lineContent.trim()
191→      ? `Regarding \`${filePath}\` line ${commentLine.lineNumber} (${sideLabel}):\n\`\`\`\n${lineContent}\n\`\`\`\n${commentText.trim()}`
192→      : `Regarding \`${filePath}\` line ${commentLine.lineNumber} (${sideLabel}): ${commentText.trim()}`;
193→    onComment(message);
194→    setCommentLine(null);
195→    setCommentText("");
196→  }
197→
198→  function handleKeyDown(e: React.KeyboardEvent) {
199→    if (e.key === "Enter" && !e.shiftKey) {
200→      e.preventDefault();
201→      handleSubmitComment();
202→    } else if (e.key === "Escape") {
203→      setCommentLine(null);
204→      setCommentText("");
205→    }
206→  }
207→
208→  if (!files) return null;
209→
210→  const options = onComment
211→    ? {
212→        themeType: "dark" as const,
213→        onLineNumberClick: handleLineNumberClick,
214→      }
215→    : { themeType: "dark" as const };
216→
217→  return (
218→    <div className="mt-1 overflow-hidden rounded-md border border-border">
219→      <MultiFileDiff
220→        oldFile={files.oldFile}
221→        newFile={files.newFile}
222→        options={options}
223→      />
224→      {commentLine && (
225→        <div className="flex items-center gap-2 border-t border-border bg-muted/50 px-2 py-1.5">
226→          <MessageSquare className="size-3 shrink-0 text-muted-foreground" />
227→          <span className="shrink-0 text-[10px] text-muted-foreground font-mono">
228→            {basename}:{commentLine.lineNumber}
229→          </span>
230→          <input
231→            ref={inputRef}
232→            type="text"
233→            value={commentText}
234→            onChange={(e) => setCommentText(e.target.value)}
235→            onKeyDown={handleKeyDown}
236→            placeholder="Comment on this line..."
237→            className="flex-1 bg-transparent text-xs outline-none placeholder:text-muted-foreground/50"
238→          />
239→          <button
240→            onClick={handleSubmitComment}
241→            disabled={!commentText.trim()}
242→            className={cn(
243→              "rounded p-1 transition-colors",
244→              commentText.trim()
245→                ? "text-primary hover:bg-primary/10"
246→                : "text-muted-foreground/30"
247→            )}
248→            title="Send comment"
249→          >
250→            <Send className="size-3" />
251→          </button>
252→          <button
253→            onClick={() => { setCommentLine(null); setCommentText(""); }}
254→            className="rounded p-1 text-muted-foreground hover:bg-muted/50 transition-colors"
255→            title="Cancel"
256→          >
257→            <X className="size-3" />
258→          </button>
259→        </div>
260→      )}
261→    </div>
262→  );
263→}
