423→/** A context menu item with a hover-triggered submenu. */
424→function ContextMenuSub({
425→  label,
426→  children,
427→}: {
428→  label: string;
429→  children: React.ReactNode;
430→}) {
431→  const [open, setOpen] = useState(false);
432→  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
433→
434→  const enter = () => {
435→    if (timeoutRef.current) clearTimeout(timeoutRef.current);
436→    setOpen(true);
437→  };
438→  const leave = () => {
439→    timeoutRef.current = setTimeout(() => setOpen(false), 150);
440→  };
441→
442→  return (
443→    <div className="relative" onMouseEnter={enter} onMouseLeave={leave}>
444→      <button className="flex w-full items-center justify-between px-3 py-1.5 text-xs transition-colors hover:bg-accent">
445→        {label}
446→        <ChevronRight className="ml-2 h-3 w-3 text-muted-foreground" />
447→      </button>
