450→          {children}
451→        </div>
452→      )}
453→    </div>
454→  );
455→}
456→
457→/** Inline input for renaming an agent. */
458→function RenameInput({
459→  initialValue,
460→  onConfirm,
461→  onCancel,
462→}: {
463→  initialValue: string;
464→  onConfirm: (value: string) => void;
465→  onCancel: () => void;
466→}) {
467→  const [value, setValue] = useState(initialValue);
468→  const inputRef = useRef<HTMLInputElement>(null);
469→
470→  useEffect(() => {
471→    inputRef.current?.focus();
472→    inputRef.current?.select();
473→  }, []);
474→
475→  function handleKeyDown(e: React.KeyboardEvent) {
476→    e.stopPropagation();
477→    if (e.key === "Enter") {
478→      const trimmed = value.trim();
479→      if (trimmed) onConfirm(trimmed);
480→      else onCancel();
481→    } else if (e.key === "Escape") {
482→      onCancel();
483→    }
484→  }
485→
486→  return (
487→    <input
488→      ref={inputRef}
489→      type="text"
490→      value={value}
491→      onChange={(e) => setValue(e.target.value)}
492→      onKeyDown={handleKeyDown}
493→      onBlur={() => {
494→        const trimmed = value.trim();
495→        if (trimmed && trimmed !== initialValue) onConfirm(trimmed);
496→        else onCancel();
497→      }}
498→      onClick={(e) => e.stopPropagation()}
499→      className="flex-1 rounded border bg-background px-1 py-0 text-xs outline-none focus:ring-1 focus:ring-ring"
500→    />
501→  );
502→}
