  if (!oldContent && newContent) return { added: newLines, removed: 0 };
  if (oldContent && !newContent) return { added: 0, removed: oldLines };
  return { added: Math.max(0, newLines - oldLines), removed: Math.max(0, oldLines - newLines) };
