  1→"use client";
  2→
  3→/**
  4→ * Syntax-highlighted diff renderer for file-modifying tool calls.
  5→ *
  6→ * Uses `@pierre/diffs` (https://diffs.com) — a Shiki-based diff library
  7→ * that renders inside Shadow DOM for style isolation.
  8→ *
  9→ * ## Data flow
 10→ *
 11→ * When Claude calls Edit, Write, or MultiEdit, the tool_use content block
 12→ * contains the file path and before/after strings. These are preserved on
 13→ * {@link ToolCallInfo.input} by `relayChatMessage()` in `use-websocket.ts`.
 14→ * This component converts that input into `oldFile`/`newFile` objects that
 15→ * `MultiFileDiff` can render.
 16→ *
 17→ * ## Tool input shapes
 18→ *
 19→ * - **Edit** — `{ file_path, old_string, new_string }` — search/replace
 20→ *   on a single region. Renders as a diff of the changed fragment only
 21→ *   (not the full file, since we don't have full-file context).
 22→ *
 23→ * - **Write** — `{ file_path, content }` — create or overwrite a file.
 24→ *   Rendered as a "new file" diff with an empty old file.
 25→ *
 26→ * - **MultiEdit** — `{ file_path, edits: [{ old_string, new_string }] }` —
 27→ *   multiple search/replace ops on the same file. The individual hunks are
 28→ *   concatenated with `\n...\n` separators since we lack inter-hunk context.
 29→ *
 30→ * ## Size guard
 31→ *
 32→ * Diffs larger than 100 KB (combined old + new) are silently skipped to
 33→ * avoid freezing the browser on whole-file Write operations.
 34→ *
 35→ * ## Commenting
 36→ *
 37→ * When `onComment` is provided, clicking a line number opens an inline
 38→ * comment input below the diff. On submit, the comment is formatted with
 39→ * file path and line context and sent to the active Claude session via
 40→ * the callback. This uses `@pierre/diffs`' `onLineNumberClick` option
 41→ * in `FileDiffOptions`.
 42→ *
 43→ * ## Usage
 44→ *
 45→ * ```tsx
 46→ * <DiffViewer toolCall={toolCallInfo} onComment={sendMessage} />
 47→ * ```
 48→ *
 49→ * Renders nothing if the tool call has no input or isn't a file-modifying tool.
 50→ *
 51→ * Used by:
 52→ * - {@link CondensedToolGroup} — inline expandable diffs in collapsed view
 53→ * - {@link Message} — automatic diffs below standalone assistant messages
 54→ * - {@link DiffsPanel} — sidebar panel collecting all session diffs
 55→ */
 56→
 57→import { useCallback, useMemo, useRef, useState } from "react";
 58→import { ChevronRight, MessageSquare, Send, X } from "lucide-react";
 59→import { MultiFileDiff } from "@pierre/diffs/react";
 60→import type { ToolCallInfo } from "@/lib/types";
 61→import { Tip } from "@/components/ui/tip";
 62→import { cn } from "@/lib/utils";
 63→
 64→// ── Tool input type guards ──────────────────────────────────────────────
 65→
 66→/** Shape of the `input` object for the Claude Code `Edit` tool. */
 67→interface EditInput {
 68→  file_path: string;
 69→  old_string: string;
 70→  new_string: string;
 71→}
 72→
 73→/** Shape of the `input` object for the Claude Code `Write` tool. */
 74→interface WriteInput {
 75→  file_path: string;
 76→  content: string;
 77→}
 78→
 79→/** Shape of the `input` object for the Claude Code `MultiEdit` tool. */
 80→interface MultiEditInput {
 81→  file_path: string;
 82→  edits: Array<{ old_string: string; new_string: string }>;
 83→}
 84→
 85→/** Skip rendering for diffs exceeding this combined size (bytes). */
 86→const MAX_CONTENT_SIZE = 100_000;
 87→
 88→/**
 89→ * Build `{ oldFile, newFile }` from a tool call's raw input.
 90→ *
 91→ * Each tool has a different input shape — this function normalizes them
 92→ * into the `{ name, contents }` format that `MultiFileDiff` expects.
 93→ * Returns `null` when the tool call can't be rendered (wrong tool,
 94→ * missing fields, or content too large).
 95→ */
 96→function buildDiffFiles(tc: ToolCallInfo): {
 97→  oldFile: { name: string; contents: string };
 98→  newFile: { name: string; contents: string };
 99→} | null {
100→  if (!tc.input) return null;
101→
102→  if (tc.name === "Edit") {
103→    const input = tc.input as unknown as EditInput;
104→    if (!input.file_path || input.old_string == null || input.new_string == null) return null;
105→    if (input.old_string.length + input.new_string.length > MAX_CONTENT_SIZE) return null;
106→    return {
107→      oldFile: { name: input.file_path, contents: input.old_string },
108→      newFile: { name: input.file_path, contents: input.new_string },
109→    };
110→  }
111→
112→  if (tc.name === "Write") {
113→    const input = tc.input as unknown as WriteInput;
114→    if (!input.file_path || input.content == null) return null;
115→    if (input.content.length > MAX_CONTENT_SIZE) return null;
116→    return {
117→      oldFile: { name: input.file_path, contents: "" },
118→      newFile: { name: input.file_path, contents: input.content },
119→    };
120→  }
121→
122→  if (tc.name === "MultiEdit") {
123→    const input = tc.input as unknown as MultiEditInput;
124→    if (!input.file_path || !Array.isArray(input.edits)) return null;
125→    const oldParts: string[] = [];
126→    const newParts: string[] = [];
127→    for (const edit of input.edits) {
128→      if (edit.old_string != null) oldParts.push(edit.old_string);
129→      if (edit.new_string != null) newParts.push(edit.new_string);
130→    }
131→    const oldContent = oldParts.join("\n...\n");
132→    const newContent = newParts.join("\n...\n");
133→    if (oldContent.length + newContent.length > MAX_CONTENT_SIZE) return null;
134→    return {
135→      oldFile: { name: input.file_path, contents: oldContent },
136→      newFile: { name: input.file_path, contents: newContent },
137→    };
138→  }
139→
140→  return null;
141→}
142→
143→/** Tool dot colors matching condensed-tool-group palette. */
144→const TOOL_DOT: Record<string, string> = {
145→  Edit: "bg-yellow-400",
146→  Write: "bg-green-400",
147→  MultiEdit: "bg-yellow-400",
148→};
149→
150→/** Count added/removed lines from old and new content strings. */
151→function countChanges(oldContent: string, newContent: string): { added: number; removed: number } {
152→  const oldLines = oldContent ? oldContent.split("\n").length : 0;
153→  const newLines = newContent ? newContent.split("\n").length : 0;
154→  if (!oldContent && newContent) return { added: newLines, removed: 0 };
155→  if (oldContent && !newContent) return { added: 0, removed: oldLines };
156→  return { added: Math.max(0, newLines - oldLines), removed: Math.max(0, oldLines - newLines) };
157→}
158→
159→/** Get the line content from the appropriate file given the side. */
160→function getLineContent(
161→  files: { oldFile: { contents: string }; newFile: { contents: string } },
162→  lineNumber: number,
163→  side: string,
164→): string {
165→  const contents = side === "additions" ? files.newFile.contents : files.oldFile.contents;
166→  const lines = contents.split("\n");
167→  return lines[lineNumber - 1] ?? "";
168→}
169→
170→/**
171→ * Renders a syntax-highlighted diff for a single file-modifying tool call.
172→ *
173→ * @param toolCall — The tool call info with `input` data.
174→ * @param onComment — Optional callback to send a comment message to the
175→ *   active Claude session. When provided, line numbers become clickable.
176→ */
177→export function DiffViewer({
178→  toolCall,
179→  onComment,
180→  defaultExpanded = false,
181→}: {
182→  toolCall: ToolCallInfo;
183→  onComment?: (message: string) => void;
184→  defaultExpanded?: boolean;
185→}) {
186→  const files = useMemo(() => buildDiffFiles(toolCall), [toolCall]);
187→  const [expanded, setExpanded] = useState(defaultExpanded);
188→  const [commentLine, setCommentLine] = useState<{ lineNumber: number; side: string } | null>(null);
189→  const [commentText, setCommentText] = useState("");
190→  const inputRef = useRef<HTMLInputElement>(null);
191→
192→  const filePath = String(toolCall.input?.file_path ?? "unknown");
193→  const basename = filePath.split("/").pop() ?? filePath;
194→  const changes = useMemo(
195→    () => files ? countChanges(files.oldFile.contents, files.newFile.contents) : { added: 0, removed: 0 },
196→    [files],
197→  );
